import{_ as n,o as e,c as i,a1 as t}from"./chunks/framework.DxqwKiYY.js";const s="/pelatihan-webgis-big/assets/image1.WDnu1KXv.png",g="/pelatihan-webgis-big/assets/image2.DGtIO1vn.png",r="/pelatihan-webgis-big/assets/image3.BCiR7Nsb.png",p="/pelatihan-webgis-big/assets/image.9nzzHd_f.png",l="/pelatihan-webgis-big/assets/image5.x7VI97n9.png",m="/pelatihan-webgis-big/assets/image6.Bb4zFQIm.png",o="/pelatihan-webgis-big/assets/image7.CLhKlS2s.png",u="/pelatihan-webgis-big/assets/image8.CyAg8bjc.png",d="/pelatihan-webgis-big/assets/image9.nb9LJ5cD.png",k="/pelatihan-webgis-big/assets/image10.D7MqodeC.png",b="/pelatihan-webgis-big/assets/image11.CieMXG7h.png",h="/pelatihan-webgis-big/assets/image12.DDjapEFB.png",c="/pelatihan-webgis-big/assets/image13.Do3hD1vy.png",_="/pelatihan-webgis-big/assets/image14.BjUF7_HI.png",f="/pelatihan-webgis-big/assets/image%201.BT5J9Tw0.png",D="/pelatihan-webgis-big/assets/image%202.C9_y_jNs.png",y="/pelatihan-webgis-big/assets/image17.lz_j01cc.png",w="/pelatihan-webgis-big/assets/image%203.B5QkPq36.png",j="/pelatihan-webgis-big/assets/image19.BWiI_rMU.png",C="/pelatihan-webgis-big/assets/image20.Dvvz0AQG.png",P="/pelatihan-webgis-big/assets/image21.C8CHb5h6.png",T="/pelatihan-webgis-big/assets/image22.DSg0fCv_.png",S="/pelatihan-webgis-big/assets/image23.CRSqGbsQ.png",I="/pelatihan-webgis-big/assets/image24.Br9hVye0.png",v="/pelatihan-webgis-big/assets/image%204.BUNs4ZYd.png",x="/pelatihan-webgis-big/assets/image%205.Cwn1V2aL.png",B="/pelatihan-webgis-big/assets/image27.Smrm4mE6.png",A="/pelatihan-webgis-big/assets/image28.CJWhFbvv.png",M="/pelatihan-webgis-big/assets/image%206.KSoxP5sT.png",L="/pelatihan-webgis-big/assets/image30.Dlo-3PHm.png",q="/pelatihan-webgis-big/assets/image31.CyBOlbs6.png",V="/pelatihan-webgis-big/assets/image%207.ol-nFXiP.png",G="/pelatihan-webgis-big/assets/image%208.BoeU8kIk.png",H="/pelatihan-webgis-big/assets/image34.ILAkPHVj.png",K="/pelatihan-webgis-big/assets/image%209.Bc4OT049.png",W="/pelatihan-webgis-big/assets/image36.u8Wp7CTV.png",z="/pelatihan-webgis-big/assets/image%2010.o6SHCroA.png",J="/pelatihan-webgis-big/assets/image38.CYz_aiXA.png",E="/pelatihan-webgis-big/assets/image39.D7u4Pkix.png",U="/pelatihan-webgis-big/assets/image40.YG6AqOXQ.png",F="/pelatihan-webgis-big/assets/image41.BJmwmGE0.png",R="/pelatihan-webgis-big/assets/image42.SptXH2IM.png",X="/pelatihan-webgis-big/assets/image43.DLaXALMe.png",N="/pelatihan-webgis-big/assets/image44.DaCvvDss.png",O="/pelatihan-webgis-big/assets/image%2011.BfKg5dXk.png",Q="/pelatihan-webgis-big/assets/image%2012.CVzN1qAP.png",Y="/pelatihan-webgis-big/assets/image%2013.CY3cKMwD.png",ga=JSON.parse('{"title":"Impor dan Pengelolaan Aset 3D dan 3D Tiles","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Impor dan Pengelolaan Aset 3D dan 3D Tiles.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Impor dan Pengelolaan Aset 3D dan 3D Tiles.md"}'),$={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Impor dan Pengelolaan Aset 3D dan 3D Tiles.md"};function Z(aa,a,na,ea,ia,ta){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="impor-dan-pengelolaan-aset-3d-dan-3d-tiles" tabindex="-1">Impor dan Pengelolaan Aset 3D dan 3D Tiles <a class="header-anchor" href="#impor-dan-pengelolaan-aset-3d-dan-3d-tiles" aria-label="Permalink to &quot;Impor dan Pengelolaan Aset 3D dan 3D Tiles&quot;">​</a></h1><h2 id="pembuatan-akun-cesium" tabindex="-1"><strong>Pembuatan Akun Cesium</strong> <a class="header-anchor" href="#pembuatan-akun-cesium" aria-label="Permalink to &quot;**Pembuatan Akun Cesium**&quot;">​</a></h2><ol><li><p>Buka tautan halaman cesium melalui <a href="https://ion.cesium.com/signin/" target="_blank" rel="noreferrer">https://ion.cesium.com/signin/</a> kemudian buat akun terlebih dahlu, jika sudah memiliki akun klik <strong>sign in.</strong></p><p><img src="'+s+'" alt=""></p></li><li><p>Berikut in merupakan tampilan awal halaman cesium. Tahap berikutnya buka menu <strong>access token</strong> yang akan digunakan untuk mendapatkan token cesium untuk proses pengembangan kedepannya.</p><p><img src="'+g+'" alt=""></p></li><li><p>Tahap berikutnya klik C<strong>reate token</strong> lalu input <strong>name</strong> dan pilih <strong>expiration</strong> untuk menentukan berapa lama token ini dapat digunakan, lalu klik <strong>create</strong>.</p><p><img src="'+r+'" alt=""></p></li><li><p>Berikut ini merupakan hasil token yang sudah dibuat, kemudian simpan token ini dan gunakan pada pengembangan web cesium ditahap berikutnya.</p><p><img src="'+p+'" alt="image.png"></p></li></ol><h2 id="menambahkan-model-3d-ke-peta-cesiumjs" tabindex="-1"><strong>Menambahkan Model 3D ke Peta CesiumJS</strong> <a class="header-anchor" href="#menambahkan-model-3d-ke-peta-cesiumjs" aria-label="Permalink to &quot;**Menambahkan Model 3D ke Peta CesiumJS**&quot;">​</a></h2><ol><li><p>Pada tahap pertama buat file baru didalam folder <strong>components</strong> dengan nama <strong>addModel3D.jsx</strong>.</p><p><img src="'+l+'" alt=""></p></li><li><p>Tahap kedua buat fungsi addModel3D yang digunakan untuk menambahkan dan mengatur model 3D pada Cesium Viewer. Kemudian tambahkan parameter berupa <strong>viewer</strong> dan <strong>opsi</strong>.</p><p><img src="'+m+'" alt=""></p></li><li><p>Tahap ketiga didalam fungsi tersebut, buat variabel <strong>const Cesium = window.Cesium;</strong> yang digunakan untuk mengambil library Cesium yang telah dimuat pada browser.</p><p><img src="'+o+'" alt=""></p></li><li><p>Kemudian pada tahap keempat buat fungsi untuk mengambil data konfigurasi model 3D dari parameter opsi, seperti lokasi file model, koordinat, ketinggian, skala, arah hadap, dan nama model, sekaligus menetapkan nilai bawaan apabila beberapa konfigurasi tidak diberikan.</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya pada tahap kelima, buat fungsi untuk posisi model berdasarkan koordinat geografis dengan merubah menjadi koordinat kartersian menggunakan fungsi <strong>Cesium.Cartesian3.fromDegrees()</strong> untuk mengubah koordinat longitude, latitude, dan ketinggian menjadi posisi yang dapat digunakan untuk menempatkan model pada peta 3D.</p><p><img src="'+d+'" alt=""></p></li><li><p>Pada tahap keenam buat fungsi untuk membuat pengaturan orientasi atau arah model 3D agar posisi hadap model dapat ditentukan pada peta.</p><p><img src="'+k+'" alt=""></p></li><li><p>Selanjutnya pada tahap ketujuh didalam fungsi sebelumnya yaitu fungsi <strong>Cesium.Transforms.headingPitchRollQuaternion</strong> tambahkan parameter untuk menentukan posisi dan arah hadap model 3D berdasarkan lokasi model serta nilai heading yang telah diatur sebelumnya.</p><p><img src="'+b+'" alt=""></p></li><li><p>Pada tahap kedelapan buat fungsi berupa <strong>return viewer.entities.add</strong> untuk menambahkan objek atau model 3D ke dalam Cesium Viewer agar dapat ditampilkan pada peta 3D.</p><p><img src="'+h+'" alt=""></p></li><li><p>Tahap terakhir, pada fungsi kedelapan tambahkan parameter untuk melakukan konfigurasi properti model 3D yang digunakan untuk mengatur nama, posisi, arah hadap, tampilan, lokasi file, ukuran, dan ukuran minimum model saat ditampilkan pada Cesium Viewer.</p><p><img src="'+c+'" alt=""></p></li></ol><h2 id="menambahkan-model-3d-tiles-ke-peta-cesiumjs" tabindex="-1"><strong>Menambahkan Model 3D Tiles ke Peta CesiumJS</strong> <a class="header-anchor" href="#menambahkan-model-3d-tiles-ke-peta-cesiumjs" aria-label="Permalink to &quot;**Menambahkan Model 3D Tiles ke Peta CesiumJS**&quot;">​</a></h2><ol><li><p>Tahap pertama buat file baru pada folder <strong>components</strong> dengan nama <strong>ad3DTileset.jsx</strong> untuk menambahkan data 3D Tiles ke dalam Cesium Viewer. Selanjutnya tambahkan parameter <strong>viewer, opsi</strong> dan <strong>selesai.</strong></p><p><img src="'+_+'" alt=""></p></li><li><p>Selanjutnya buat fungsi <strong>const Cesium = window.Cesium;</strong> yang digunakan untuk mengambil library Cesium yang telah dimuat pada browser.</p><p><img src="'+f+'" alt="image.png"></p></li><li><p>Pada tahap ketiga buat fungsi untuk mengambil konfigurasi 3D tiles berupa URL, Asset ID, nama layer, dan pengaturan zoom otomatis dari parameter opsi.</p><p><img src="'+D+'" alt="image.png"></p></li><li><p>Selanjutnya pada tahap kelima buat variabel <strong>let proses;</strong> yang digunakan untuk menyimpan proses pemuatan data 3D Tiles sebelum hasilnya ditampilkan.</p><p><img src="'+y+'" alt=""></p></li><li><p>Pada tahap keenam buat kondisi menggunakan <strong>if</strong> untuk memeriksa apakah terdapat <strong>assetId</strong>, kemudian memuat data 3D Tiles dari Cesium ion menggunakan Asset ID yang telah diberikan.</p><p><img src="'+w+'" alt="image.png"></p></li><li><p>Selanjutnya pada tahap ketujuh buat kondisi <strong>else if</strong> memeriksa apakah terdapat url, kemudian memuat data 3D Tiles dari alamat URL yang telah ditentukan menggunakan <strong>Cesium.Cesium3DTileset.fromUrl()</strong>.</p><p><img src="'+j+'" alt=""></p></li><li><p>Kemudian pada tahap kedelapan buat kondisi <strong>if (selesai)</strong> untuk menghentikan proses pemuatan dan mengembalikan nilai null melalui fungsi selesai apabila sumber data 3D Tiles tidak tersedia.</p><p><img src="'+C+'" alt=""></p></li><li><p>Tahap kesembilan buat fungsi untuk menjalankan proses berikutnya setelah data 3D Tiles berhasil dimuat, kemudian menerima hasil data dalam variabel tileset.</p><p><img src="'+P+'" alt=""></p></li><li><p>Selanjutnya didalam fungsi tersebut tambahkan variabel <strong>tileset.show</strong> untuk mengatur agar data 3D dapat diproses pada peta.</p><p><img src="'+T+'" alt=""></p></li><li><p>Selanjutnya buat fungsi untuk menambahkan data 3D Tiles ke dalam Cesium Viewer agar dapat ditampilkan pada peta.</p><p><img src="'+S+'" alt=""></p></li><li><p>Tahap berikutnya lanjutkan dengan membuat kondisi <strong>if (otomatisZoom)</strong> untuk mengarahkan kamera secara otomatis ke lokasi 3D Tiles apabila fitur otomatis zoom diaktifkan.</p><p><img src="'+I+'" alt=""></p></li><li><p>Kemudian tahap terakhir buat kondisi <strong>if (selesai)</strong> untuk menjalankan fungsi selesai dan mengirimkan objek tileset setelah data 3D Tiles berhasil dimuat.</p><p><img src="'+v+'" alt="image.png"></p></li></ol><h2 id="pembuatan-panel-3d-aset" tabindex="-1"><strong>Pembuatan Panel 3D Aset</strong> <a class="header-anchor" href="#pembuatan-panel-3d-aset" aria-label="Permalink to &quot;**Pembuatan Panel 3D Aset**&quot;">​</a></h2><ol><li><p>Tahap pertama buat fungsi untuk menampilkan panel layer dengan membuat fungsi <strong>addPanelLayer3D</strong> serta tambahkan parameter <strong>viewer</strong> dan <strong>daftarLayer</strong>.</p><p><img src="'+x+'" alt="image.png"></p></li><li><p>Kemudian tahap kedua buat elemen <strong>div</strong> menggunakan JavaScript.</p><p><img src="'+B+'" alt=""></p></li><li><p>Selanjutnya pada tahap ketiga buat fungsi untuk mengatur posisi dan tampilan panel dengan menggunakan styling css meliputi <strong>position: absolut</strong> untuk membuat posisi panel bebas. Kemudian <strong>top: 50px</strong> merupakan jarak dari atas, <strong>right: 50px</strong> merupakan jarak dari kanan. Lalu <strong>background: white</strong> merupakan <strong>Warna latar putih</strong>, kemudian <strong>padding</strong> untuk memberikan jarak isi panel. Selanjutnya buat <strong>border-radius</strong> untuk membuat sudut panel melengkung serta <strong>min-width</strong> untuk menentukan lebar minimum panel.</p><p><img src="'+A+'" alt=""></p></li><li><p>Tahap keempat buat panel menggunakan properti innerHTML. Pada tahap ini, elemen <code>&lt;div&gt;</code> digunakan untuk menampilkan teks &quot;Layer 3D&quot;, kemudian diberikan styling agar judul terlihat lebih tegas dan memiliki jarak dengan daftar layer yang akan ditampilkan di bawahnya.</p><p><img src="'+M+'" alt="image.png"></p></li><li><p>Pada tahap kelima buat fungsi untuk melakukan perulangan pada setiap data layer menggunakan Object.entries() dan forEach(), kemudian ambil nama serta objek dari masing-masing layer untuk digunakan dalam proses pembuatan kontrol layer secara otomatis.</p><p><img src="'+L+'" alt=""></p></li><li><p>Tahap ketujuh buat fungsi <strong>if</strong> untuk periksa terlebih dahulu apakah objek layer tersedia, kemudian jika layer tersedia buat elemen label sebagai wadah untuk menampilkan kontrol checkbox dan nama dari setiap layer.</p><p><img src="'+q+'" alt=""></p></li><li><p>Selanjutnya pada tahap kedelapan buat fungsi untuk mengatur tampilan elemen baris menggunakan css agar checkbox dan nama layer tersusun secara horizontal, sejajar, memiliki jarak antar elemen, serta memberikan tampilan yang lebih interaktif ketika pengguna mengarahkan kursor ke kontrol layer.</p><p><img src="'+V+'" alt="image.png"></p></li><li><p>Pada tahap kesembilan buat fungsi menggunakan properti <strong>innerHTML</strong> untuk menambahkan isi HTML ke dalam elemen baris. Isi tersebut berupa checkbox yang digunakan untuk mengontrol visibilitas layer dan nama layer.</p><p><img src="'+G+'" alt="image.png"></p></li><li><p>Selanjutnya tambahkan tambahkan fungsi pada checkbox untuk mengatur tampilan layer. Script <strong>querySelector(&#39;input&#39;)</strong> digunakan untuk memilih elemen checkbox, sedangkan <strong>addEventListener(&#39;change&#39;)</strong> digunakan untuk mendeteksi perubahan saat pengguna mencentang atau menghilangkan centang. Nilai <strong>e.target.checked</strong> kemudian digunakan untuk mengatur properti <strong>objek.show,</strong> sehingga layer akan ditampilkan ketika checkbox aktif dan disembunyikan ketika checkbox tidak aktif.</p><p><img src="'+H+'" alt=""></p></li><li><p>Tahap berikutnya buat fungsi untuk menambahkan kontrol layer kedalam panel dengan menggunakan <strong>appendChild()</strong> untuk menambahkan elemen baris yang berisi checkbox dan nama layer.</p><p><img src="'+K+'" alt="image.png"></p></li><li><p>Pada tahap terakhir, tambahkan elemen panel ke dalam container Cesium Viewer menggunakan <strong>appendChild().</strong> Dengan cara ini, panel kontrol layer akan tampil di atas peta. Selanjutnya, return panel digunakan untuk mengembalikan elemen panel agar dapat digunakan kembali jika diperlukan.</p><p><img src="'+W+'" alt=""></p></li><li><p>Berikut ini keseluruhan script untuk panelLayer3D.</p><p><img src="'+z+'" alt="image.png"></p></li></ol><h2 id="pemanggilan-data-3d-dalam-peta" tabindex="-1"><strong>Pemanggilan Data 3D Dalam Peta</strong> <a class="header-anchor" href="#pemanggilan-data-3d-dalam-peta" aria-label="Permalink to &quot;**Pemanggilan Data 3D Dalam Peta**&quot;">​</a></h2><ol><li><p>Tahap pertama buka file <strong>CesiumViewer.jsx</strong> lalu tambahkan Cesium Ion Access Token dibawah <strong>const CESIUM_STYLE_URL</strong> dengan menggunakan token yang sebelumnya telah dibuat pada poin A.</p><p><img src="'+J+'" alt=""></p></li><li><p>Tahap kedua pada fungsi <strong>function createViewerCesium(container) {</strong> tambahkan Cesium Ion Access Token untuk menghubungkan aplikasi dengan layanan Cesium Ion.</p><p><img src="'+E+'" alt=""></p></li><li><p>Tahap beirkutnya dibawah fungsi <strong>function createViewerCesium(container)</strong> buat fungsi baru yaitu <strong>function addContent3D(viewer)</strong> yang digunakan sebagai wadah untuk mengatur seluruh proses penambahan data dan objek 3D ke dalam Cesium Viewer.</p><p><img src="'+U+'" alt=""></p></li><li><p>Selanjutnya tambahkan data 3D Tileset ke dalam Cesium Viewer menggunakan fungsi <strong>add3DTileset()</strong>, kemudian tentukan <strong>assetId</strong> sebagai sumber data 3D, berikan nama layer, dan atur opsi <strong>otomatisZoom</strong> agar kamera tidak berpindah secara otomatis saat layer dimuat.</p><p><img src="'+F+'" alt=""></p></li><li><p>Pada tahap berikutnya setelah data 3D Tileset berhasil dimuat, gunakan fungsi callback untuk menerima objek <strong>gedung3D</strong> sehingga objek tersebut dapat digunakan pada proses selanjutnya, seperti menambahkan model 3D atau membuat kontrol layer.</p><p><img src="'+R+'" alt=""></p></li><li><p>Selanjutnya pada <strong>function (gedung3D)</strong> buat fungsi untuk menambahkan model 3D berformat GLB menggunakan fungsi <strong>addModel3D()</strong> dengan menentukan sumber file, lokasi, ketinggian, ukuran, arah, dan nama model sebelum digunakan pada tahap berikutnya.</p><p><img src="'+X+'" alt=""></p></li><li><p>Tahap terakhir dalam <strong>function (gedung3D)</strong> buat fungsi <strong>addPanelLayer3D()</strong>, kemudian masukkan objek Gedung 3D dan model GLB ke dalam daftar layer melalui checkbox pada panel.</p><p><img src="'+N+'" alt=""></p></li><li><p>Selanjutnya pada tahap terakhir pada fungsi <strong>useEffect(() =&gt; {if (status !== &#39;siap&#39; || viewerRef.current) return;</strong> panggil fungsi <strong>addContent3D()</strong> dengan mengirimkan objek <strong>viewerRef.current</strong> untuk menambahkan berbagai konten dan objek 3D ke dalam peta.</p><p><img src="'+O+'" alt="image.png"></p></li><li><p>Hasil tampilan objek 3D dalam peta dengan format tileset.</p><p><img src="'+Q+'" alt="image.png"></p></li><li><p>Hasil tampilan objek 3D dengan menggunakan model data glb.</p><p><img src="'+Y+'" alt="image.png"></p></li></ol>',11)])])}const ra=n($,[["render",Z]]);export{ga as __pageData,ra as default};
